export default async function formatDeviceData(context, data) {
  console.log('[UTIL formatDeviceData] Tetiklendi, Gelen Payload:', data);
  const temp = data.temp || 0;
  const status = temp > 80 ? 'CRITICAL' : (temp > 50 ? 'WARNING' : 'NORMAL');
  return { temperature: temp.toFixed(2) + ' °C', status, timestamp: new Date().toISOString() };
}

