console.log('[GATEWAY] Modbus - MQTT Gateway Başlatıldı...');
const crypto = require('node:crypto');
const deviceId = 'demo_sensor_001';
const secretKey = 'demo_secret_12345';

while (true) {
   try {
      const data = await readModbusData('127.0.0.1', 8502, 1, 0, 1, 'holding', 'uint16');
      console.log('[GATEWAY] Okunan Modbus verisi:', data);

      const temp = data[0] || 0;
      const formatted = await utils.formatDeviceData({ temp });

      const timestamp = new Date().toISOString();
      const rawPayloadString = JSON.stringify(formatted);
      const dataToSign = `${deviceId}|${timestamp}|${rawPayloadString}`;

      const hmac = crypto.createHmac('sha256', secretKey).update(dataToSign).digest('hex');

      const mqttMessage = {
          deviceId,
          timestamp,
          payload: formatted,
          hmac
      };

      await publishMQTT('telemetry/demo_sensor_001', mqttMessage);
      console.log('[GATEWAY] MQTT üzerinden güvenli telemetri atıldı!');
   } catch (err) {
      console.error('[GATEWAY] Modbus okuma hatası:', err.message);
   }
