}; return {
setup() {
    const sensorData = ref({});
    const wsLogs = ref([]);
    const loading = ref(false);
    const { $toast } = useNuxtApp();
    const { t } = useI18n();

    const { ws } = useWS('/api/ws/demo/ws', (payload) => {
       console.log('[UI] WS Mesajı Alındı:', payload);
       wsLogs.value.unshift({ time: new Date().toLocaleTimeString(), msg: JSON.stringify(payload) });
       if (wsLogs.value.length > 50) wsLogs.value.pop();

       if (payload?.type === 'sensor_update') {
         sensorData.value = payload.data;
       }
    });

    onMounted(() => {
      console.log('[UI] Sayfa yüklendi, WebSocket dinleniyor...');
    });

    const checkStatus = async () => {
      console.log('[UI] REST API\'ye istek atılıyor (/api/demo/status)...');
      loading.value = true;
      try {
        const res = await $fetch('/api/demo/status', { method: 'POST' });
        console.log('[UI] REST API Cevabı:', res);
        if (res.success) {
           sensorData.value = res.data;
           $toast.success(res.message || 'Başarılı!');
        } else {
           $toast.error(res.error || 'Hata oluştu');
        }
      } catch (e) {
         console.error('[UI] REST İstek Hatası:', e);
         $toast.error('Bağlantı hatası');
      } finally {
         loading.value = false;
      }
    };

    const sendWsPing = () => {
      console.log('[UI] WS üzerinden ping gönderiliyor...');
      if (ws.value && ws.value.readyState === 1) {
        ws.value.send(JSON.stringify({ action: 'ping' }));
        $toast.info('WS Ping gönderildi!');
      } else {
        $toast.error('WS Bağlantısı henüz açık değil');
      }
    };

    return { sensorData, wsLogs, checkStatus, loading, sendWsPing };
  }
}; function __dummy() {
